let started=false,audioContext,master,scheduler,nextNote=0,step=0,musicOn=false;
const themeButton=document.querySelector('#theme'),soundButton=document.querySelector('#sound');
function setTheme(dark){document.documentElement.dataset.theme=dark?'dark':'light';themeButton.setAttribute('aria-pressed',String(dark));themeButton.setAttribute('aria-label',dark?'Aktifkan mode terang':'Aktifkan mode gelap');themeButton.title=themeButton.getAttribute('aria-label');themeButton.innerHTML='◐ <span>'+(dark?'Light mode':'Dark mode')+'</span>';try{localStorage.setItem('subhi-theme',dark?'dark':'light')}catch{}}
let savedTheme;try{savedTheme=localStorage.getItem('subhi-theme')}catch{}setTheme(savedTheme==='dark');themeButton.onclick=()=>setTheme(document.documentElement.dataset.theme!=='dark');
// Original two-channel chiptune, synthesized locally. No external audio or tracking.
const melody=[76,0,79,83,81,79,76,74,72,0,76,79,78,76,74,71,69,0,72,76,74,72,71,67,69,71,72,74,71,0,67,0];
const bass=[48,48,43,43,45,45,41,43];
function tone(note,time,duration,volume,type='square'){if(!note)return;const osc=audioContext.createOscillator(),g=audioContext.createGain();osc.type=type;osc.frequency.value=440*Math.pow(2,(note-69)/12);g.gain.setValueAtTime(0,time);g.gain.linearRampToValueAtTime(volume,time+.012);g.gain.setValueAtTime(volume,time+duration*.65);g.gain.exponentialRampToValueAtTime(.0001,time+duration);osc.connect(g);g.connect(master);osc.start(time);osc.stop(time+duration+.02)}
function schedule(){while(nextNote<audioContext.currentTime+.3){tone(melody[step%32],nextNote,.23,.12);if(step%2===0)tone(bass[Math.floor(step/4)%8],nextNote,.42,.15,'triangle');step++;nextNote+=.255}}
async function sound(on){try{if(on){if(!audioContext){audioContext=new(window.AudioContext||window.webkitAudioContext)();master=audioContext.createGain();master.gain.value=.22;master.connect(audioContext.destination)}await audioContext.resume();master.gain.setTargetAtTime(.22,audioContext.currentTime,.04);nextNote=audioContext.currentTime+.04;clearInterval(scheduler);schedule();scheduler=setInterval(schedule,100)}else if(audioContext){clearInterval(scheduler);master.gain.setTargetAtTime(0,audioContext.currentTime,.03)}musicOn=on;soundButton.setAttribute('aria-pressed',String(on));soundButton.setAttribute('aria-label',on?'Matikan musik':'Aktifkan musik');soundButton.title=soundButton.getAttribute('aria-label');soundButton.innerHTML='♫ <span>Sound '+(on?'on':'off')+'</span>'}catch{soundButton.innerHTML='♫ <span>Audio unavailable</span>';musicOn=false}}
soundButton.onclick=()=>sound(!musicOn);
function start(){if(started)return;started=true;document.querySelector('#start-panel').hidden=true;document.querySelector('#game-menu').hidden=false;document.querySelector('#menu-status').textContent='SELECT YOUR NEXT CHAPTER';document.querySelector('#game-menu [data-go="portofolio"]').focus({preventScroll:true})}
document.querySelector('#start').onclick=start;
document.addEventListener('keydown',e=>{if(e.target.closest?.('.language-switch, .global-navigation, input, textarea, select'))return;if(e.altKey||e.ctrlKey||e.metaKey||document.querySelector('dialog[open]'))return;const onMenu=!document.querySelector('[data-screen="menu"]').hidden;if(!onMenu){if(e.key==='Escape'){location.hash='menu';e.preventDefault()}return}if(!started&&e.key==='Enter'){if(e.target.closest?.('a,button')&&!e.target.closest('#start'))return;e.preventDefault();start();return}if(started&&['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const buttons=[...document.querySelectorAll('#game-menu button')],i=buttons.indexOf(document.activeElement);buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length].focus()}});
// Suspend music while the tab is out of sight; retain the user's sound choice.
document.addEventListener('visibilitychange',()=>{if(!audioContext)return;if(document.hidden)audioContext.suspend();else if(musicOn){nextNote=audioContext.currentTime+.04;audioContext.resume()}});
